import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;int n = Integer.parseInt(line1.trim());StringTokenizer st = new StringTokenizer(br.readLine());double sum = 0;for (int i = 0; i < n; i++) {sum += Double.parseDouble(st.nextToken());}double result = sum / n;System.out.printf("%.12f%n", result);}}